package com.portfolio.financeflow.controller;import com.portfolio.financeflow.model.Transaction;import com.portfolio.financeflow.repo.TransactionRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestController @RequestMapping("/api/transactions") @CrossOrigin(origins="http://localhost:5173")public class TransactionController{final TransactionRepository r;TransactionController(TransactionRepository r){this.r=r;}@GetMapping List<Transaction>all(@RequestParam(required=false)String type,@RequestParam(required=false)String from,@RequestParam(required=false)String to){if(type!=null)return r.findByTypeIgnoreCase(type);if(from!=null&&to!=null)return r.findByDateBetweenOrderByDateDesc(LocalDate.parse(from),LocalDate.parse(to));return r.findAll();}@PostMapping ResponseEntity<Transaction>create(@Valid @RequestBody Transaction t){return ResponseEntity.status(HttpStatus.CREATED).body(r.save(t));}@DeleteMapping("/{id}")ResponseEntity<Void>delete(@PathVariable Long id){r.deleteById(id);return ResponseEntity.noContent().build();}}
